test('replanning uses sliders summing 100 percent and updates existing plan without losing history',async()=>{const d=await boot({id:'replan'}),w=d.window,$=id=>w.document.getElementById(id);w.plannerTest.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo']}],stages:[]});w.document.querySelector('[data-tab="cycle"]').click();$('newPlanning').click();w.document.querySelector('[data-pw-path="detail"]').click();$('pwNext').click();$('pwNext').click();const exam=new Date();exam.setDate(exam.getDate()+30);$('pwExam').value=exam.toISOString().slice(0,10);$('pwNext').click();$('pwNext').click();$('pwNext').click();let slider=w.document.querySelector('[data-ratio-slider="0"]');slider.value=65;slider.dispatchEvent(new w.Event('input',{bubbles:true}));assert.equal([...w.document.querySelectorAll('[data-pw-ratio]')].reduce((n,x)=>n+Number(x.value),0),100);$('pwNext').click();let data=()=>JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:replan'));const id=data().activePlanningId;const stage=data().stages.find(s=>s.content==='Conteúdo novo');const history={id:'h',kind:'study',subjectId:'a',name:'Direito',content:stage.content,stageId:stage.id,roundId:data().roundId,planningId:id,seconds:300,countPlan:true,date:new Date().toISOString()};w.plannerTest.apply(history);w.plannerTest.configure({history:[history]});w.plannerTest.save();$('replanPlanning').click();$('pwNext').click();$('pwNext').click();assert.ok($('pwExam').value);$('pwNext').click();$('pwNext').click();$('pwNext').click();assert.equal($('pwNext').textContent,'Aplicar replanejamento');$('pwNext').click();assert.equal(data().activePlanningId,id);assert.equal(data().plannings.length,1);assert.equal(data().history.length,1);assert.equal(data().stages.reduce((n,s)=>n+s.done,0),300);$('deletePlanning').click();assert.equal($('deletePlanningDialog').open,true);$('confirmDeletePlanning').click();assert.equal(data().plannings.length,0);assert.equal(data().stages.length,0);assert.equal(data().history.length,1);assert.equal(data().archivedPlannings.length,1);$('restorePlanning').click();assert.equal(data().plannings.length,1);assert.equal(data().activePlanningId,id);assert.equal(data().stages.reduce((n,s)=>n+s.done,0),300);w.close();});

