test('SEE-DF and fiscal catalogs import independently without mixing shared subjects or duplicating topics',async()=>{const d=await boot({id:'catalogs'}),w=d.window,$=id=>w.document.getElementById(id);w.document.querySelector('[data-tab="edital"]').click();$('editalSeedImport').click();$('editalSeeImport').click();let see=w.plannerTest.edital().subjects.filter(m=>m.sourceId==='see-df');assert.equal(see.length,10);assert.equal(see.reduce((n,m)=>n+m.topics.length,0),94);assert.ok(see.some(m=>m.name==='Noções de Primeiros Socorros'));$('editalSeeImport').click();assert.equal(w.plannerTest.edital().subjects.filter(m=>m.sourceId==='see-df').length,10);$('fiscalCatalogChoice').value='rfb-auditor-2022';$('loadFiscalCatalog').click();const rfb=w.plannerTest.edital().subjects.filter(m=>m.sourceId==='rfb-auditor-2022');assert.equal(rfb.length,17);assert.equal(rfb.reduce((n,m)=>n+m.topics.length,0),601);assert.ok(rfb.some(m=>m.name==='Legislação Aduaneira'));assert.equal($('editalSourceFilter').value,'rfb-auditor-2022');$('fiscalCatalogChoice').value='sefaz-ba-tributaria';$('loadFiscalCatalog').click();const ba=w.plannerTest.edital().subjects.filter(m=>m.sourceId==='sefaz-ba-tributaria');assert.equal(ba.length,12);assert.ok(ba.some(m=>m.name==='Legislação Tributária'));assert.equal(ba.reduce((n,m)=>n+m.topics.length,0),268);$('fiscalCatalogChoice').value='sefaz-ba-tributaria';$('loadFiscalCatalog').click();assert.equal(w.plannerTest.edital().subjects.filter(m=>m.sourceId==='sefaz-ba-tributaria').reduce((n,m)=>n+m.topics.length,0),268);assert.equal(w.plannerTest.edital().subjects.filter(m=>m.sourceId==='pc-ba').reduce((n,m)=>n+m.topics.length,0),379);w.close();});

 test('exam workspaces preserve independent records and combine statistics once',async()=>{const d=await boot({id:'exams'}),w=d.window,p=w.plannerTest;const legacy=p.exams()[0].id;const see=p.createExam(p.examCatalog().find(e=>e.id==='see-df'));assert.ok(see);assert.equal(p.edital().subjects.length,10);p.configure({history:[]});p.save();const rfb=p.createExam(p.examCatalog().find(e=>e.id==='rfb-auditor-2022'));assert.equal(p.edital().subjects.length,17);assert.equal(w.document.getElementById('examTopName').textContent,rfb.name);assert.equal(p.aggregate().subjects.length,27);assert.equal(p.selectExam(see.id),true);assert.equal(p.edital().subjects.length,10);assert.equal(p.selectExam(legacy),true);assert.equal(p.edital().subjects.length,0);const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:exams'));assert.equal(p.validate({format:'ciclo-estudos-backup',version:1,data:saved}).exams.length,3);p.configure({session:null});assert.equal(p.selectExam(see.id),true);w.close();});
