test('switching proof pauses timer and restores its subject and elapsed time on return',async()=>{const d=await boot({id:'exam-timer'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo']}],stages:[{id:'s',subjectId:'a',content:'Conteúdo novo',target:1800,done:0}]});const old=p.exams()[0].id;p.configure({session:{stageId:'s',elapsed:123,running:false,last:Date.now(),mode:'elapsed',phase:'work',phaseLeft:1500}});$('examTopChange').click();w.document.querySelector('[data-exam-catalog="see-df"]').click();assert.equal($('examChoiceDialog').open,false);assert.equal(p.edital().subjects.length,10);assert.equal(p.selectExam(old),true);const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:exam-timer'));assert.equal(data.session.elapsed,123);assert.equal(data.session.stageId,'s');assert.equal(data.session.running,false);w.close();});

function topicFixture(){return {id:'ed',subjectId:'a',name:'Direito',level:'intermediate',weight:1,ratios:[50,25,25],topics:[{id:'parent',number:'1',name:'Capítulo',done:false},{id:'known',number:'1.1',name:'Já estudado',done:true},{id:'new',number:'1.2',name:'Novo conteúdo',done:false}]}}
function topicConfig(){return {examDate:'',dailyHours:3,blockMinutes:25,minimumMinutes:20,topicHours:1,weekdays:[0,1,2,3,4,5,6],mode:'time'}}
test('topic curriculum covers all leaf topics, skips completed theory, and spaces followups after theory',async()=>{const d=await boot({id:'topic-plan'}),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo','Questões','Resumo (Revisão)']}],stages:[]});const plan=p.buildPlan(topicConfig(),[m]);assert.equal(plan.coverage.total,2);assert.equal(plan.coverage.known,1);assert.equal(plan.coverage.pending,1);assert.ok(!plan.stages.some(s=>s.curriculum.topicId==='parent'));assert.ok(!plan.stages.some(s=>s.curriculum.topicId==='known'&&s.curriculum.phase==='theory'));for(const id of ['known','new'])assert.ok(plan.stages.some(s=>s.curriculum.topicId===id));const sched=p.schedule(plan.stages,plan.config,{fresh:true});const theory=plan.stages.filter(s=>s.curriculum.phase==='theory').at(-1),theoryDate=sched.finishes.get(theory.curriculum.key);for(const s of plan.stages.filter(s=>s.curriculum.topicId==='new'&&s.curriculum.phase!=='theory')){const delay=(new Date(sched.finishes.get(s.curriculum.key)+'T12:00:00')-new Date(theoryDate+'T12:00:00'))/86400000;assert.ok(delay>=(s.curriculum.phase==='review'?7:3));}assert.equal(plan.coverage.outsideDeadline,0);w.close();});
test('short exam deadline reports uncovered topics without silently removing them',async()=>{const d=await boot({id:'short-topics'}),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});const date=new Date();date.setDate(date.getDate()+2);const plan=p.buildPlan({...topicConfig(),examDate:date.toISOString().slice(0,10)},[topicFixture()]);assert.equal(plan.coverage.total,2);assert.ok(plan.coverage.outsideDeadline>0);assert.ok(plan.stages.some(s=>s.curriculum.topicId==='new'&&s.curriculum.phase==='questions'));w.close();});
test('actual theory completion delays practice and records credit to exact topic block',async()=>{const d=await boot({id:'actual-topics'}),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo','Questões','Resumo (Revisão)']}],stages:[]});p.configure({edital:{subjects:[m],plan:{}}});const plan=p.buildPlan(topicConfig(),[m]);p.newPlan('Tópicos',plan.stages,plan.config);let saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:actual-topics'));const theory=saved.stages.filter(s=>s.curriculum.phase==='theory');theory.forEach(s=>s.done=s.target);p.configure({stages:saved.stages});p.save();saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:actual-topics'));assert.equal(saved.edital.subjects[0].topics.find(t=>t.id==='new').done,true);const review=saved.stages.find(s=>s.curriculum.topicId==='new'&&s.curriculum.phase==='review');assert.equal(p.stageReady(review),false);for(const s of saved.stages.filter(s=>s.curriculum.phase==='theory'))s.curriculumCompletedOn=new Date(Date.now()-8*86400000).toISOString().slice(0,10);p.configure({stages:saved.stages});assert.equal(p.stageReady(review),true);const second=theory[1],entry={subjectId:'a',content:'Conteúdo novo',topic:second.curriculum.topicName,seconds:60,roundId:p.round()};p.configure({session:{stageId:second.id,elapsed:0,running:false,last:Date.now()}});p.assign(entry);assert.equal(entry.stageId,second.id);const backup=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:actual-topics'));assert.ok(p.validate({format:'ciclo-estudos-backup',version:1,data:backup}).stages.some(s=>s.curriculum));w.close();});
test('topic task curriculum includes video lessons and keeps all required followups',async()=>{const d=await boot({id:'task-topics'}),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});const plan=p.buildPlan({...topicConfig(),mode:'task',dailyTasks:2,weeklyTasks:14,taskActivities:[{unit:'páginas',quantity:10},{unit:'questões',quantity:20},{unit:'cartões',quantity:30}],videoTasks:{enabled:true,quantity:3,theoryShare:100}},[topicFixture()]);assert.ok(plan.stages.some(s=>s.curriculum.topicId==='new'&&s.content==='Videoaula'&&s.unit==='videoaulas'&&s.target===3));assert.ok(plan.stages.some(s=>s.curriculum.topicId==='known'&&s.content==='Questões'));assert.equal(plan.coverage.total,2);w.close();});

test('complete Receita Federal curriculum fits storage and survives backup validation',async()=>{const d=await boot({id:'full-rfb'}),w=d.window,p=w.plannerTest;p.createExam(p.examCatalog().find(e=>e.id==='rfb-auditor-2022'));const plan=p.buildPlan({...topicConfig(),topicHours:2,blockMinutes:25},p.edital().subjects);assert.ok(plan.coverage.total>400);assert.ok(plan.stages.length<=5000);const made=p.newPlan('Receita completa',plan.stages,plan.config);assert.ok(made,'Full curriculum must save within browser storage quota');const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:full-rfb'));assert.ok(p.validate({format:'ciclo-estudos-backup',version:1,data}).stages.length>1000);const stored=w.localStorage.getItem('ciclo-estudos-v1:cloud:full-rfb');w.eval(readFileSync('cloud-ui.js','utf8'));const full=p.validate({format:'ciclo-estudos-backup',version:1,data});const pending=w.cloudStateJSON(full);w.localStorage.setItem('ciclo-estudos-v1:cloud:full-rfb:sync',JSON.stringify({version:1,pending:{payload:JSON.parse(pending)}}));assert.equal(w.cloudHydrateState(JSON.parse(pending)).plannings[0].data.stages.length,full.stages.length);w.close();const loaded=await boot({id:'full-rfb'},stored);assert.ok(loaded.window.plannerTest.plans()[0].data.stages.length>1000);assert.equal(loaded.window.plannerTest.exams().find(e=>e.sourceId==='rfb-auditor-2022').data.subjects.length,17);loaded.window.close();});

test('calendar repeats only maintenance after the first topic pass and limits dated plans to before exam',async()=>{const d=await boot({id:'topic-repeat'}),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});p.configure({edital:{subjects:[m],plan:{}}});const plan=p.buildPlan(topicConfig(),[m]);p.newPlan('Conteúdo',plan.stages,plan.config);const end=new Date();end.setDate(end.getDate()+50);const projected=p.project(end),future=Object.values(projected).flat().filter(b=>b.round>0);assert.ok(future.length>0);const ids=new Set(plan.stages.filter(s=>s.curriculum.phase==='theory').map(s=>s.curriculum.key));const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:topic-repeat'));assert.ok(future.every(b=>!ids.has(data.stages.find(s=>s.id===b.stageId).curriculum.key)));for(const s of data.stages)s.done=s.target;p.configure({stages:data.stages});p.save();w.document.getElementById('finishCycle').click();const after=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:topic-repeat'));assert.ok(after.stages.every(s=>s.curriculum.phase!=='theory'));assert.equal(after.edital.plan.maintenance,true);w.close();});

test('edital edits planning and recorded hours are immediately queued and confirmed in database adapter',async()=>{const d=await boot({id:'cloud-every-change'},null,true),w=d.window,p=w.plannerTest,{cloud,writes}=w.testCloud;p.createExam(p.examCatalog().find(e=>e.id==='see-df'));await cloud.sync.flush();const m=p.edital().subjects[0];m.topics[0].done=true;p.save();await cloud.sync.flush();assert.equal(writes.at(-1).edital.subjects[0].topics[0].done,true);p.newPlan('Nuvem',[{subjectId:m.subjectId,content:'Conteúdo novo',target:1800,done:0}],topicConfig());await cloud.sync.flush();assert.equal(writes.at(-1).plannings.at(-1).name,'Nuvem');const h={id:'study-cloud',kind:'study',subjectId:m.subjectId,name:m.name,seconds:900,date:new Date().toISOString(),content:'Conteúdo novo',roundId:p.round()};p.configure({history:[h]});p.save();await cloud.sync.flush();assert.equal(writes.at(-1).history[0].seconds,900);assert.equal(cloud.sync.pending,null);assert.match(w.document.getElementById('cloudStatus').textContent,/Salvo na nuvem/);assert.match(w.document.getElementById('cloudStatus').title,/Supabase/);const original=w.Storage.prototype.setItem;w.Storage.prototype.setItem=()=>{throw new Error('quota')};m.topics[0].done=false;assert.equal(p.save(),true);await cloud.sync.flush();assert.equal(writes.at(-1).edital.subjects[0].topics[0].done,false);w.Storage.prototype.setItem=original;w.close();});

