test('automatic planning times use routine domain and completed-topic study history',async()=>{const d=await boot({id:'auto-estimates'}),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo']}],stages:[]});const config=topicConfig(),first=p.autoTimes(config,[m]);assert.equal(first.minimumMinutes,20);assert.ok(first.blockMinutes>=20&&first.blockMinutes<=60);assert.equal(first.estimationSources.a,'dominio');const beginner=p.autoTimes(config,[{...m,level:'beginner'}]);assert.ok(beginner.subjectTopicHours.a>first.subjectTopicHours.a);p.configure({history:[{id:'old',kind:'study',subjectId:'a',topic:'1.1 · Já estudado',content:'Conteúdo novo',seconds:2700,date:new Date().toISOString()}]});const observed=p.autoTimes(config,[m]);assert.equal(observed.subjectTopicHours.a,.75);assert.equal(observed.estimationSources.a,'historico');const plan=p.buildPlan({...config,...observed},[m]);const theory=plan.stages.filter(s=>s.curriculum.topicId==='new'&&s.curriculum.phase==='theory');assert.ok(theory.length>0);assert.ok(theory.reduce((n,s)=>n+s.target,0)>=.75*3600);w.close();});

