test('topic plan interleaves new theory with practice from studied topics and rejects unknown review-only topics',async()=>{const d=await boot({id:'interleaved'}),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Revisão','Conteúdo novo','Questões']}],stages:[]});const plan=p.buildPlan(topicConfig(),[m]),byKey=new Map(plan.stages.map(s=>[s.curriculum.key,s]));const schedule=p.schedule(plan.stages,plan.config,{fresh:true}),first=Object.values(schedule.output).flat().slice(0,3).map(b=>byKey.get(b.stageId));assert.deepEqual(first.map(s=>s.curriculum.phase),['theory','review','questions']);assert.equal(first[0].curriculum.topicId,'new');assert.equal(first[1].curriculum.topicId,'known');assert.equal(first[2].curriculum.topicId,'known');assert.equal(first[1].content,'Revisão');assert.throws(()=>p.buildPlan(topicConfig(),[{...m,ratios:[0,50,50]}]),/ainda não estudados/);const known={...m,ratios:[0,50,50],topics:m.topics.map(t=>({...t,done:true}))};assert.ok(p.buildPlan(topicConfig(),[known]).stages.every(s=>s.curriculum.phase!=='theory'));w.close();});
