test('SEFAZ law split preserves topic ids progress history and generic old records through reload and backup',async()=>{const user={id:'law-split'},d=await boot(user),w=d.window,p=w.plannerTest;const topics=[{id:'con',number:'1',name:'Direito Constitucional - Conceitos de teoria do Estado.',done:true},{id:'adm',number:'42',name:'Direito Administrativo - Atos Administrativos: Perfeição, validade e eficácia;',done:false}];p.set({subjects:[{id:'law',name:'Direito Constitucional e Administrativo',color:'#315fb3',contents:['Revisão']}],stages:[]});p.configure({edital:{subjects:[{id:'old-ed',subjectId:'law',sourceId:'sefaz-ba-tributaria',name:'Direito Constitucional e Administrativo',topics,level:'intermediate',weight:2,ratios:[30,45,25]}],plan:{}}});p.newPlan('Anterior',[{subjectId:'law',content:'Revisão',target:1800,done:0,curriculum:{key:'old-ed:adm:review',phase:'review',topicId:'adm',topicName:'42 · '+topics[1].name,editalSubjectId:'old-ed'}},{subjectId:'law',content:'Questões',target:1800,done:0}],topicConfig());p.configure({history:[{id:'old-adm',kind:'study',subjectId:'law',name:'Direito Constitucional e Administrativo',content:'Revisão',topic:topics[1].name,seconds:600,date:new Date().toISOString()},{id:'old-generic',kind:'study',subjectId:'law',name:'Direito Constitucional e Administrativo',content:'Questões',seconds:300,date:new Date().toISOString()}]});p.save();const stored=w.localStorage.getItem('ciclo-estudos-v1:cloud:law-split');w.close();const d2=await boot(user,stored),v=d2.window,q=v.plannerTest;const data=JSON.parse(v.localStorage.getItem('ciclo-estudos-v1:cloud:law-split')),adm=data.edital.subjects.find(m=>m.name==='Direito Administrativo'),con=data.edital.subjects.find(m=>m.name==='Direito Constitucional');assert.ok(adm&&con);assert.equal(con.topics[0].id,'con');assert.equal(con.topics[0].done,true);assert.equal(adm.topics[0].id,'adm');assert.equal(data.stages[0].subjectId,adm.subjectId);assert.equal(data.stages[0].curriculum.editalSubjectId,adm.id);assert.equal(data.history[0].subjectId,adm.subjectId);assert.equal(data.history[1].subjectId,'law');assert.equal(data.history.reduce((n,h)=>n+h.seconds,0),900);assert.ok(data.subjects.find(m=>m.id==='law').legacyCombinedLaw);assert.equal(q.validate({format:'ciclo-estudos-backup',version:1,data}).edital.subjects.length,2);for(const c of q.examCatalog().filter(e=>e.id.startsWith('sefaz-ba'))){assert.ok(c.seed.some(m=>m.name==='Direito Constitucional'));assert.ok(c.seed.some(m=>m.name==='Direito Administrativo'));assert.ok(!c.seed.some(m=>m.name==='Direito Constitucional e Administrativo'))}v.close();});

test('review suggestions use cumulative counts across activities and periods with strict 80 percent threshold',async()=>{const d=await boot({id:'performance-review'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]},{id:'b',name:'Contabilidade',color:'#315fb3',contents:[]}],stages:[]});p.configure({history:[{id:'old',kind:'study',subjectId:'a',topic:'Atos administrativos',content:'Conteúdo novo',correct:1,wrong:9,seconds:600,date:'2025-01-01T12:00:00Z'},{id:'new',kind:'study',subjectId:'a',topic:'Atos administrativos',content:'Questões',correct:9,wrong:1,seconds:600,date:new Date().toISOString()},{id:'exact',kind:'study',subjectId:'b',topic:'Balanço',content:'Questões',correct:8,wrong:2,seconds:600,date:new Date().toISOString()},{id:'empty',kind:'study',subjectId:'a',topic:'Sem questões',seconds:600,date:new Date().toISOString()}]});p.save();const suggestions=p.suggestions();assert.equal(suggestions.length,2);assert.ok(suggestions.every(g=>g.percentage===50&&g.total===20));w.document.querySelector('[data-tab="home"]').click();assert.match(w.document.querySelector('.performance-review-panel').textContent,/50% de acertos/);assert.match(w.document.querySelector('.performance-review-panel').textContent,/10 de 20 questões/);w.document.querySelector('[data-tab="statistics"]').click();assert.equal(w.document.querySelectorAll('.performance-review-panel').length,1);const index=suggestions.findIndex(g=>g.kind==='topic');w.document.querySelector('[data-performance-review="'+index+'"]').click();assert.equal($('manualReviewDialog').open,true);assert.equal($('manualReviewSubject').value,'a');assert.equal($('manualReviewContent').value,'Atos administrativos');$('manualReviewDialog').close();p.configure({history:[]});w.document.querySelector('[data-tab="home"]').click();assert.equal(w.document.querySelector('.performance-review-panel'),null);w.close();});

