test('questions start three days after theory and existing plans retain progress when the interval is updated',async()=>{const user={id:'three-day-questions'},d=await boot(user),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});const plan=p.buildPlan(topicConfig(),[m]),questions=plan.stages.filter(s=>s.curriculum.topicId==='new'&&s.curriculum.phase==='questions');assert.ok(questions.length);assert.ok(questions.every(s=>s.curriculum.delayDays===3));const schedule=p.schedule(plan.stages,plan.config,{fresh:true}),first=questions[0],completed=schedule.finishes.get(first.curriculum.after),starts=Object.entries(schedule.output).filter(([,blocks])=>blocks.some(b=>b.stageId===first.curriculum.key)).map(([date])=>date).sort();assert.equal((new Date(starts[0]+'T12:00:00')-new Date(completed+'T12:00:00'))/86400000,3);p.newPlan('Anterior',plan.stages,plan.config);const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:three-day-questions'));for(const data of [saved,saved.plannings[0].data,...saved.exams.map(e=>e.data)])for(const stage of data.stages||[])if(stage.curriculum?.phase==='questions'&&stage.curriculum.after){stage.curriculum.delayDays=14;stage.done=123;}const imported=p.validate({format:'ciclo-estudos-backup',version:1,data:structuredClone(saved)});assert.ok(imported.stages.filter(s=>s.curriculum?.phase==='questions'&&s.curriculum.after).every(s=>s.curriculum.delayDays===3&&s.done===123));w.close();const loaded=await boot(user,JSON.stringify(saved)),after=JSON.parse(loaded.window.localStorage.getItem('ciclo-estudos-v1:cloud:three-day-questions'));assert.ok(after.stages.filter(s=>s.curriculum?.phase==='questions'&&s.curriculum.after).every(s=>s.curriculum.delayDays===3&&s.done===123));assert.ok(after.plannings[0].data.stages.filter(s=>s.curriculum?.phase==='questions'&&s.curriculum.after).every(s=>s.curriculum.delayDays===3));loaded.window.close();});

test('merged multi-exam plans keep independent contexts records and additive progress valid for cloud restore',async()=>{const d=await boot({id:'merge-app'}),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});p.newPlan('Base',[{subjectId:'a',content:'Conteúdo novo',target:3600,done:0}],topicConfig());const base=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:merge-app')),local=structuredClone(base),remote=structuredClone(base),stage=local.stages[0];for(const [payload,id]of [[local,'h-local'],[remote,'h-remote']]){payload.stages[0].done=600;payload.history.push({id,kind:'study',name:'Direito',subjectId:'a',stageId:stage.id,countPlan:true,roundId:payload.roundId,content:'Conteúdo novo',seconds:600,date:new Date().toISOString()});}remote.subjects[0].name='Direito atualizado';const merged=mergeSnapshots(base,local,remote),valid=p.validate({format:'ciclo-estudos-backup',version:1,data:merged});assert.equal(valid.history.length,2);assert.equal(valid.stages[0].done,1200);assert.equal(valid.plannings[0].data.stages[0].done,1200);assert.equal(valid.subjects[0].name,'Direito atualizado');w.close();});

test('new planning inherits completed topics and partial theory from prior plans without crediting questions as theory',async()=>{const d=await boot({id:'carryover-plans'}),w=d.window,p=w.plannerTest,m=topicFixture();m.topics.forEach(t=>t.done=false);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});p.configure({edital:{subjects:[m],plan:{}}});p.newPlan('Anterior',[{subjectId:'a',content:'Conteúdo novo',target:1800,done:0,curriculum:{key:'old-known',phase:'theory',topicId:'known',topicName:'1.1 · Já estudado',editalSubjectId:'ed'}},{subjectId:'a',content:'Conteúdo novo',target:3600,done:0,curriculum:{key:'old-new',phase:'theory',topicId:'new',topicName:'1.2 · Novo conteúdo',editalSubjectId:'ed'}}],topicConfig());const stored=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:carryover-plans'));stored.stages[0].done=1800;stored.stages[1].done=1800;p.configure({stages:stored.stages,history:[{id:'theory-old',kind:'study',subjectId:'a',stageId:stored.stages[0].id,topic:'1.1 · Já estudado',content:'Conteúdo novo',seconds:1800,date:'2026-01-01T12:00:00Z'}]});p.save();const fresh=p.buildPlan(topicConfig(),[m]);assert.ok(!fresh.stages.some(s=>s.curriculum.topicId==='known'&&s.curriculum.phase==='theory'));const partial=fresh.stages.filter(s=>s.curriculum.topicId==='new'&&s.curriculum.phase==='theory');assert.ok(partial.length);assert.equal(partial.reduce((n,s)=>n+s.target,0),2400);assert.ok(fresh.config.studyCarryover.knownTopics>0);p.configure({history:[{id:'only-questions',kind:'study',subjectId:'a',topic:'1.2 · Novo conteúdo',content:'Questões',seconds:900,correct:10,wrong:1,date:new Date().toISOString()}],stages:[],plannings:[],archivedPlannings:[]});const untouched={...m,topics:m.topics.map(t=>({...t,done:false}))};const reviewOnly=p.buildPlan(topicConfig(),[untouched]);assert.ok(reviewOnly.stages.some(s=>s.curriculum.topicId==='new'&&s.curriculum.phase==='theory'));w.close();});

test('devices editing different active plans merge both plans while keeping the local selection',async()=>{const d=await boot({id:'merge-plan-context'}),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});const a=p.newPlan('A',[{subjectId:'a',content:'Revisão',target:1800,done:0}],topicConfig()),b=p.newPlan('B',[{subjectId:'a',content:'Questões',target:1800,done:0}],topicConfig());p.switchPlan(a.id);const base=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:merge-plan-context')),local=structuredClone(base),remote=structuredClone(base),bp=remote.plannings.find(plan=>plan.id===b.id);remote.activePlanningId=b.id;for(const key of ['stages','roundId','initialCompletedCycles','goals','planner','measurementMode'])remote[key]=structuredClone(bp.data[key]);remote.edital.plan=structuredClone(bp.data.editalPlan);for(const [payload,id]of [[local,'ha'],[remote,'hb']]){payload.stages[0].done=600;payload.history.push({id,name:'Direito',kind:'study',subjectId:'a',stageId:payload.stages[0].id,seconds:600,date:new Date().toISOString()})}const merged=p.validate({format:'ciclo-estudos-backup',version:1,data:mergeSnapshots(base,local,remote)});assert.equal(merged.activePlanningId,a.id);assert.equal(merged.stages[0].id,local.stages[0].id);assert.equal(merged.stages[0].done,600);assert.equal(merged.plannings.find(plan=>plan.id===b.id).data.stages[0].done,600);assert.equal(merged.history.length,2);w.close();});

test('receiving another device update preserves the local running timer and updates cached study progress',async()=>{const d=await boot({id:'live-receive'},null,true),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});p.newPlan('Ativo',[{subjectId:'a',content:'Revisão',target:1800,done:0}],topicConfig());await w.testCloud.cloud.sync.flush();const remote=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:live-receive'));remote.subjects[0].name='Direito atualizado';remote.stages[0].done=600;remote.plannings[0].data.stages[0].done=600;remote.session=null;p.configure({session:{stageId:remote.stages[0].id,elapsed:123,running:true,last:Date.now(),mode:'elapsed',phase:'work',phaseLeft:1500}});w.testCloud.cloud.sync.onRemote(remote);const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:live-receive'));assert.equal(data.session.running,true);assert.ok(data.session.elapsed>=123&&data.session.elapsed<125);assert.equal(data.stages[0].done,600);assert.equal(data.subjects[0].name,'Direito atualizado');w.close();});

